  function render(){const main=$('#content'),scroll=main.scrollTop,focused=document.activeElement,focusKey=main.contains(focused)?focused.dataset.focusKey:null,opened=new Map($$('[data-fold]').map(d=>[d.dataset.fold,d.open]));$('#accountcount').textContent=visible().length+' accounts';$('#navcount').textContent=visible().length;const local=runs().filter(r=>r.computer==='dev').length,remote=runs().length-local;$('#livecount').textContent=local+' live · '+remote+' elsewhere';const first=S.onlyIds!==null;$('#navcost').textContent=first?'$0':'$184';$('#mcpcount').textContent=first?'0':'11';$('#skillcount').textContent=first?'0':'255';$('#appupdatecount').textContent=first?'0':'1';$('#projectcount').textContent=first?'0':'23';$('#livegrid').style.opacity=runs().length?'1':'.15';$('#livegrid').setAttribute('aria-label',runs().length+' live sessions');$('#pinnednav').hidden=first;$('#updatestatus').textContent=first?'':' · 1 update';$('#computerchip').innerHTML=first?'<i class="dot"></i> 1 computer':'<i class="dot"></i><i class="dot"></i><i class="dot"></i> 3 computers';$('#computerchip').setAttribute('aria-label',first?'1 computer, online':'3 computers, all online');$('#fresh').innerHTML=S.empty||first&&!visible().some(a=>a.windows.length)?'Limits not read<br>No usage yet':S.fresh;$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===S.page));main.innerHTML=S.empty&&(S.page==='Overview'||S.page==='Accounts')?empty():S.page==='Overview'?overview():S.page==='Accounts'?accounts():placeholder();$$('[data-fold]').forEach(d=>{if(opened.has(d.dataset.fold))d.open=opened.get(d.dataset.fold)});main.querySelectorAll('button,input,select,summary').forEach((el,i)=>{el.dataset.focusKey=el.id||[el.tagName,...[...el.attributes].filter(a=>a.name.startsWith('data-')&&a.name!=='data-focus-key').map(a=>a.name+'='+a.value)].join('|')+(el.tagName==='SUMMARY'?'|'+(el.parentElement.dataset.fold||i):'')});if(focusKey){const replacement=[...main.querySelectorAll('[data-focus-key]')].find(el=>el.dataset.focusKey===focusKey);replacement?.focus({preventScroll:true})}main.scrollTop=scroll;main.dataset.redraws=String(+(main.dataset.redraws||0)+1);const rm=$('#roommode');if(rm)rm.onchange=()=>{S.used=rm.value==='used';render()};const cf=$('#computerfilter');if(cf)cf.onchange=()=>{S.computer=cf.value;render()};const ac=$('#activitycomputer');if(ac){ac.value=S.activity;ac.onchange=()=>{S.activity=ac.value;$('#yearclock').innerHTML=clock(S.activity)}};const ut=$('#usedtoggle');if(ut)ut.onchange=()=>S.used=ut.checked}
